229	    /**
230	     * Randomly populate a single field location.
231	     * The creation checks are evaluated in the existing priority order.
232	     * @param location The location to populate.
233	     */
234	    private void populateLocation(Location location)
235	    {
236	        if(tryPopulate(animals, location, LION_CREATION_PROBABILITY,
237	            loc -> new Lion(true, field, loc))) {
238	            return;
239	        }
240	        if(tryPopulate(animals, location, CHEETAH_CREATION_PROBABILITY,
241	            loc -> new Cheetah(true, field, loc))) {
242	            return;
243	        }
244	        if(tryPopulate(animals, location, GAZELLE_CREATION_PROBABILITY,
245	            loc -> new Gazelle(true, field, loc))) {
246	            return;
247	        }
248	        if(tryPopulate(animals, location, JAGUAR_CREATION_PROBABILITY,
249	            loc -> new Jaguar(true, field, loc))) {
250	            return;
251	        }
252	        if(tryPopulate(plants, location, PLANT_CREATION_PROBABILITY,
253	            loc -> new Grass(true, field, loc))) {
254	            return;
255	        }
256	        if(tryPopulate(animals, location, ZEBRA_CREATION_PROBABILITY,
257	            loc -> new Zebra(true, field, loc))) {
258	            return;
259	        }
260	        tryPopulate(animals, location, HUNTER_CREATION_PROBABILITY,
261	            loc -> new Hunter(field, loc));
262	    }
