264	    /**
265	     * Try to add a randomly created actor to the target population.
266	     * @param population The destination population list.
267	     * @param location The location to populate.
268	     * @param creationProbability The probability threshold for creation.
269	     * @param factory The actor factory to use when the random check succeeds.
270	     * @return true if an actor was created and added.
271	     */
272	    private boolean tryPopulate(List<Actor> population, Location location,
273	        double creationProbability, ActorFactory factory)
274	    {
275	        if(rand.nextDouble() <= creationProbability) {
276	            population.add(factory.create(location));
277	            return true;
278	        }
279	        return false;
280	    }
